// Source: st04.ecl.txt MainSub04 1220-1238 (entry), GirlD01 607-632,
//         GirlD01_at 634-684 (dependency).  Chapter/boss gate and -9905 gating dropped
//         per approved policy; the selected formation and its schedule are kept.
// Source frame 0 == card frame ~120 (opening buffer). TIME_LIMIT = 120 + 2400 window + 4.
const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// TH15 type 12 (arrowhead) -> existing modern slot 352 + 12*16; base radius 2.4, color 2 valid.
const TH15_ARROWHEAD: int = 544;
const ARROW_COLOR: int = 2;

// GirlD01_at EX chain (etEx append): ANIM(a=1, birth anim omitted), WAIT(60), ACCEL(120).
// ACCEL: a=120 frames, r=accel (difficulty), s=-999999 -> keep current bullet angle.
// Birth ANIM / retreat (position -= 4*velocity) applied at spawn via sh_dist; anim wait omitted.
xformdef GIRL_BULLET(accel: fx) {
    wait(60);                                    // etEx WAIT a=60
    @120 set_gravity(at_effect(accel * cos($self_angle)),
                     at_effect(accel * sin($self_angle)));   // etEx ACCEL a=120
    set_gravity(0fx, 0fx);                        // ACCEL expires after 120 frames
}

// GirlD01_at: 600 volleys, 10 frames apart. etAim(0,10) = fixed alternating-layer ring:
//   angle(i,q) = alpha + (-1)^q * (R(i) + H(m,q)), R(i)=i*65536/n, delta=1deg;
//   speeds s0=0.3, s1=0.1 with mode-10 index k=(q+m%2)&~1.
// etCount(0, [-1], [-2]) -> count=[-1], layers=[-2]:
//   count: E5 N5 H6 L7 ; layers: E1 N3 H3 L3.
async sub girl_attack() {
    var rank: int = global(GVAR_RANK);
    var n: int = 5;
    var m: int = 1;
    if rank >= RANK_NORMAL { m = 3; }
    if rank >= RANK_HARD { n = 6; }
    if rank >= RANK_LUNATIC { n = 7; }
    var accel: fx = 0.03fx;                       // ACCEL r: E/N 0.03, H 0.032, L 0.035
    if rank == RANK_HARD { accel = 0.032fx; }
    if rank == RANK_LUNATIC { accel = 0.035fx; }

    wait(60);                                     // GirlD01_at line 637
    sh_reset(0);
    sh_sprite(0, TH15_ARROWHEAD, ARROW_COLOR);    // etSprite(0,12,2)
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_xform(0, GIRL_BULLET(accel));

    var delta: int = 182;                         // source 0.017453292 rad = 1deg
    var base: int = aim_player() as int;          // %A = ANGLE_PLAYER, sampled once (line 673)
    var left: int = 600;                          // $B
    while left > 0 {
        left = left - 1;
        for q in 0..m {
            var k: int = ((q + (m % 2)) / 2) * 2;
            var speed: fx = 0.3fx;
            if m > 1 {
                var frac: fx = (k as fx) / ((m - 1) as fx);
                speed = 0.3fx + (0.1fx - 0.3fx) * frac;
            }
            var h: int = ((q + 1) / 2) * delta;   // H(m,q), odd m
            if m % 2 == 0 { h = (q / 2) * delta + delta / 2; }
            var lb: int = base + h;               // (-1)^q applied to layer offset
            if q % 2 != 0 { lb = base - h; }
            sh_angle(0, lb as angle, 0deg);
            sh_speed(0, speed, 0fx);
            sh_dist(0, 0fx - 4fx * speed);        // ANIM retreat position -= 4*velocity
            sh_fire(0);                           // etOn(0)
        }
        base = base + 40504;                      // %A += 3.883222 rad
        wait(10);
    }
}

// GirlD01: create config + movement + async attack.  f1 = inherited %F1 (BAM), halved here.
async sub girl(f1: int) {
    set_invuln(65535);
    set_hurtbox(16fx);                            // setHurtbox(32,32) circular -> r=16
    set_hitbox(12fx);                             // setHitbox(24,24) circular -> r=12
    var half: int = f1 / 2;                        // %F1 = %F1 / 2
    move_vel(0, (30948 - half) as angle, 2.5fx, EASE_LINEAR); // moveVel(pi-0.17453292-F1, 2.5)
    move_speed(70, 0fx, EASE_QUAD_IN);            // moveSpeedTime(70,1,0.0)
    spawn girl_attack();
    wait(40);
    move_speed(120, 0.2fx, EASE_QUAD_IN);         // moveSpeedTime(120,1,0.2)
    wait(120);
    move_speed(120, 2.5fx, EASE_QUAD_IN);         // moveSpeedTime(120,1,2.5)
    loop { wait(1000); }                          // GirlD01_612/_632 idle loop
}

// MainSub04: wait 300, then 14 spawns 100 frames apart on a 60deg arc.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(300);                                    // MainSub04 line 1223
    for iter in 0..14 {                           // $D=14 loop
        var f1: int = rand(65536) / 6;            // %F1 = %RANDF * pi/3 rad (BAM)
        var f0: int = 0 - f1;                     // %F0 = 0 - %F1
        var ax: fx = 128fx * cos(f0 as angle);    // circlePos(%A,%B,%F0,128)
        var ay: fx = 128fx * sin(f0 as angle);
        // enmCreateF("GirlD01", 192+A, 0+B, 1000, 1000, 1); F-gate dropped.
        _ = spawn_enemy(192fx + ax, ay, 1000, 0, 1000, 0, girl(f1));
        wait(100);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
